"""W009 memory probe: on a FRESH wallet-rpc, record VmHWM/VmRSS/RssAnon after open+refresh, then after building n-input
txs in ascending order (VmHWM is monotonic, so each step shows what that n needs). sweep_all do_not_relay only.
usage: memprobe.py <port> <pid> <arm> <out csv> <n,n,...>"""
import json, os, sys, time, urllib.request
port, pid, arm, out, ns = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3], sys.argv[4], [int(x) for x in sys.argv[5].split(",")]
URL = f"http://127.0.0.1:{port}/json_rpc"
def rpc(m, p=None, timeout=7200):
    r = json.loads(urllib.request.urlopen(urllib.request.Request(URL, data=json.dumps({"jsonrpc": "2.0", "id": 0, "method": m, "params": p or {}}).encode(),
        headers={"Content-Type": "application/json"}), timeout=timeout).read())
    if "error" in r: raise RuntimeError(f"{m}: {r['error']}")
    return r["result"]
def mem():
    d = {}
    for l in open(f"/proc/{pid}/status"):
        k = l.split(":")[0]
        if k in ("VmHWM", "VmRSS", "RssAnon"): d[k] = int(l.split()[1])
    return d
WAVE = 37499954878
new = not os.path.exists(out)
f = open(out, "a")
if new: f.write("arm,step,n,wall_s,VmHWM_kB,VmRSS_kB,RssAnon_kB\n")
def row(step, n, w):
    m = mem(); line = f"{arm},{step},{n},{w:.2f},{m['VmHWM']},{m['VmRSS']},{m['RssAnon']}"; f.write(line + "\n"); f.flush(); print(line, flush=True)
row("started", 0, 0)
rpc("open_wallet", {"filename": "w006", "password": ""}, timeout=600); rpc("refresh", {}, timeout=1200)
row("opened+refreshed", 0, 0)
tr = rpc("incoming_transfers", {"transfer_type": "available", "account_index": 0})["transfers"]
pool = sorted([t for t in tr if t["amount"] == WAVE], key=lambda t: t["global_index"])[:max(ns)]
addr = rpc("get_address", {"account_index": 0})["address"]
for n in ns:
    for t in pool[:n]: rpc("thaw", {"key_image": t["key_image"]})
    t0 = time.time()
    res = rpc("sweep_all", {"address": addr, "account_index": 0, "subaddr_indices_all": True, "do_not_relay": True, "priority": 0})
    w = time.time() - t0
    for t in pool[:n]: rpc("freeze", {"key_image": t["key_image"]})
    spent = [k for x in res.get("spent_key_images_list", []) for k in x.get("key_images", [])]
    assert len(spent) == n and set(spent) == {t["key_image"] for t in pool[:n]}, "wrong inputs"
    row("after_tx", n, w)
rpc("close_wallet", {})
